import sys
s = sys.stdin.read().strip()
stack = []
mapping = {')': '(', '}': '{', ']': '['}
valid = True
for ch in s:
    if ch in mapping.values():
        stack.append(ch)
    elif ch in mapping:
        if not stack or stack.pop() != mapping[ch]:
            valid = False
            break
if stack:
    valid = False
print('VALID' if valid else 'INVALID')
